import type { NextRequest } from "next/server"
import { NextResponse } from "next/server"

// The site is a single page for now. Every other route stays in the codebase
// but answers 404 until it is added here.
const PUBLIC_PATHS = new Set([
  "/",
  "/resume.pdf",
  "/llms.txt",
  "/index.md", // rewritten to /llms.txt in next.config.ts
  "/sitemap.xml",
  "/robots.txt",
  "/manifest.webmanifest",
])

// opengraph-image and twitter-image are generated by src/app and served with
// a cache-busting query string.
const PUBLIC_PREFIXES = [
  "/images/",
  "/icons/",
  "/opengraph-image",
  "/twitter-image",
]

// Root-level assets from public/ (logo.svg, favicons). Excludes .md and .json
// so the markdown and registry routes stay private.
const PUBLIC_ASSET = /^\/[^/]+\.(svg|png|ico|jpe?g|webp)$/

export function proxy(request: NextRequest) {
  const { pathname } = request.nextUrl

  if (
    PUBLIC_PATHS.has(pathname) ||
    PUBLIC_PREFIXES.some((prefix) => pathname.startsWith(prefix)) ||
    PUBLIC_ASSET.test(pathname)
  ) {
    return NextResponse.next()
  }

  return NextResponse.rewrite(new URL("/_not-found", request.url), {
    status: 404,
  })
}

export const config = {
  matcher: ["/((?!_next/|__nextjs).*)"],
}
